308	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
309	    private static final Map<String, String> CITY_REGION = Map.of(
310	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
311	
312	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
313	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
314	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
315	
316	    /** Fixed region-to-IANA-timezone table used to derive {@link #getTimezone()}. */
317	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
318	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
319	
320	    /**
321	     * The fixed city-to-region mapping ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
322	     * {@code Brisbane -> QLD}): the region for {@code city}, or {@code null} when the city is not in
323	     * the table. Used only by postcode validation, which branches on "known region or not" by testing
324	     * for {@code null} before range-checking the postcode.
325	     */
326	    public static String regionOf(String city) {
327	        return CITY_REGION.get(city);
328	    }
