330	    /**
331	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
332	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
333	     * absent, not a 4-digit number, or in no known range.
334	     */
335	    public static String regionOfPostcode(String postcode) {
336	        if (postcode == null || postcode.isEmpty()) {
337	            return null;
338	        }
339	        int value;
340	        try {
341	            value = Integer.parseInt(postcode);
342	        } catch (NumberFormatException ex) {
343	            return null;
344	        }
345	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
346	            int[] range = entry.getValue();
347	            if (value >= range[0] && value <= range[1]) {
348	                return entry.getKey();
349	            }
350	        }
351	        return null;
352	    }
