387	    /**
388	     * A single Luhn check digit (0-9) derived at response time over the digits contained in
389	     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
390	     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
391	     * digit from the right, subtracting 9 from any result over 9, and taking
392	     * {@code (10 - sum % 10) % 10}. Not persisted.
393	     */
394	    public Integer getCheckDigit() {
395	        if (this.customerCode == null) {
396	            return null;
397	        }
398	        int sum = 0;
399	        boolean dbl = true;
400	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
401	            char c = this.customerCode.charAt(i);
402	            if (c < '0' || c > '9') {
403	                continue;
404	            }
405	            int d = c - '0';
406	            if (dbl) {
407	                d *= 2;
408	                if (d > 9) {
409	                    d -= 9;
410	                }
411	            }
412	            sum += d;
413	            dbl = !dbl;
414	        }
415	        return (10 - (sum % 10)) % 10;
416	    }
417	
418	    /**
419	     * A display-only derived string composing the owner's canonical contact and household values:
420	     * {@code normalizedTelephone|email|householdId}, joined with '|'. The telephone is stored in
421	     * canonical E.164 form and the email lower-cased; an absent email or householdId contributes an
422	     * empty segment. Derived at response time and exposed as a read-only response field only — it
423	     * drives no check. Duplicate detection is purely household-based (see
424	     * {@code CheckOwnerHouseholdUnique}, which compares {@link #getHouseholdId() householdId}); this
425	     * key is not consulted. Not persisted.
426	     */
427	    public String getIdentityKey() {
428	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
429	    }
430	
431	    private static String keyPart(String value) {
432	        return value == null ? "" : value;
433	    }
434	
435	    /**
436	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
437	     * national digits (everything after the country code) grouped in threes and space-separated —
438	     * e.g. {@code +61412345678} becomes {@code +61 412 345 678}. The country code is recognised for
439	     * '+61' (2 digits) and '+1' (1 digit); any other prefix falls back to a 2-digit country code.
440	     * {@code null} when the telephone is absent or not a valid E.164 value. Derived at response time
441	     * and not persisted; the raw {@link #getTelephone() telephone} stays in E.164 form.
442	     */
443	    public String getTelephoneDisplay() {
444	        if (this.telephone == null || !this.telephone.matches("\\+\\d{8,15}")) {
445	            return null;
446	        }
447	        String digits = this.telephone.substring(1);
448	        int countryCodeLength;
449	        if (digits.startsWith("61")) {
450	            countryCodeLength = 2;
451	        }
452	        else if (digits.startsWith("1")) {
453	            countryCodeLength = 1;
454	        }
455	        else {
456	            countryCodeLength = 2;
457	        }
458	        String countryCode = digits.substring(0, countryCodeLength);
459	        String national = digits.substring(countryCodeLength);
460	        StringBuilder display = new StringBuilder("+").append(countryCode);
461	        for (int i = 0; i < national.length(); i += 3) {
462	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
463	        }
464	        return display.toString();
465	    }
